"""Compile the WildStar WMO pixel shader into an embedded D3D9 bytecode header."""
import hashlib
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
import build_sky_shaders as base

SOURCE = ROOT / "wowdecomp/WoW/Source/WorldClient/Shaders/WildStarWmo.hlsl"
TARGET = SOURCE.with_name("WildStarWmoBytecode.h")


def main():
    source = SOURCE.read_bytes()
    code = base.compile_shader(source, "ps_3_0")
    parts = [
        "// Generated by tools/build_ws_wmo_shader.py; source SHA256 " + hashlib.sha256(source).hexdigest(),
        "#pragma once", "#include <cstdint>", "namespace WildStarWmoBytecode {",
        "inline constexpr uint8_t Pixel[] = {",
    ]
    parts.extend("    " + ",".join(f"0x{x:02x}" for x in code[i:i + 24]) + "," for i in range(0, len(code), 24))
    parts += ["};", "}"]
    TARGET.write_text("\n".join(parts) + "\n", encoding="utf-8")
    print("ps_3_0", len(code), "bytes")


if __name__ == "__main__":
    main()
